/* @autogenerated */
import { Slide, RepositoryProvider, UploadProgress, DownloadBlob } from '../repository-provider.interface';
import { filter, map, mergeMap, Observable } from 'rxjs';
import { HttpEvent, HttpEventType, HttpParams, HttpResponse } from '@angular/common/http';
import { ApiService } from '@shared/data/api/api.service';
import { Acl, AclAllow, AclVisibility } from '@shared/data/acl/acl.model';
import { LongTask } from '@shared/data/long-task.model';
import { pollUntil } from '@shared/data/poll-until';

/** Respuesta del endpoint de ACL. */
export interface AclResponse {
  allows?: { [key: string]: { name?: string; allowed?: boolean; reason?: string } };
  fields?: AclVisibility;
}

const toDate = (value: unknown) => (typeof value === 'string' ? new Date(value) : (value as Date | undefined));

/** Las fechas de la tarea y de sus pasos llegan como ISO-8601. */
const withTaskDates = (task: LongTask): LongTask => ({
  ...task,
  startTime: toDate(task.startTime),
  endTime: toDate(task.endTime),
  steps: (task.steps ?? []).map((step) => ({ ...step, startTime: toDate(step.startTime), endTime: toDate(step.endTime) })),
});

const isLongTaskDone = (task: LongTask) => task.detailStatus === 'FAILED' || task.detailStatus === 'FINISHED';

export class ApiProvider<T, F> implements RepositoryProvider<T, F> {
  constructor(
    private readonly key: string,
    private readonly api: ApiService,
    private readonly bodyUrl: string,
    private readonly aclUrl: string,
  ) {}
  acl(key: string | null): Observable<Acl> {
    return this.api
      .get<AclResponse>(this.aclUrl + (key ? '/' + encodeURIComponent(key) : ''))
      .pipe(map((val) => this.formatAcl(val)));
  }
  list(query: F): Observable<Slide<T>> {
    return (this.api.get(this.bodyUrl, new HttpParams().appendAll(query as any)) as Observable<any>).pipe(
      map((value) => {
        const queryString = value.next ? value.next.split('?')[1] : ''; // Extrae la parte después de '?'
        const next = queryString ? Object.fromEntries(new URLSearchParams(queryString)) : {};
        return {
          next: next,
          hasNext: value.hasNext,
          content: value.items,
        };
      }),
    );
  }
  retrieve(key: string): Observable<T> {
    return this.api.get<T>(this.bodyUrl + '/' + encodeURIComponent(key));
  }
  add(item: T): Observable<T> {
    return this.api.post(this.bodyUrl, item) as Observable<T>;
  }
  update(key: string, item: T): Observable<T> {
    return this.api.put<T>(this.bodyUrl + '/' + encodeURIComponent(key), item);
  }
  patch(key: string, data: any, path?: string): Observable<T> {
    return this.api.patch<T>(this.bodyUrl + '/' + encodeURIComponent(key) + (path ? '/' + path : ''), data);
  }
  patchAllForQuery(of: string, query: F, data: any): Observable<LongTask> {
    return this.api
      .patch<{ uid: string }>(this.bodyUrl + '/~/' + of, data, new HttpParams().appendAll(query as any))
      .pipe(mergeMap((res) => this.pollTask(res.uid, this.bodyUrl + '/~/' + of + '-status/' + res.uid)));
  }
  delete(key: string): Observable<void> {
    return this.api.delete<void>(this.bodyUrl + '/' + encodeURIComponent(key));
  }
  deleteAllForQuery(query: F): Observable<LongTask> {
    return this.api
      .delete<{ uid: string }>(this.bodyUrl, new HttpParams().appendAll(query as any))
      .pipe(mergeMap((res) => this.pollTask(res.uid, this.bodyUrl + '/~/delete-status/' + res.uid)));
  }

  downloadFile(endpoint: string): Observable<DownloadBlob> {
    return this.api.download(endpoint).pipe(
      map((response: HttpResponse<Blob>) => {
        const blob = response.body!;
        const contentDisposition = response.headers.get('Content-Disposition') || '';
        const fileName = this.extractFileNameFromHeader(contentDisposition) || 'downloaded_file';
        return new DownloadBlob(blob, fileName);
      }),
    );
  }

  storeFile(endpoint: string, name: string, file: File): Observable<UploadProgress> {
    return this.api.upload(this.bodyUrl + endpoint, name, file).pipe(
      filter((event: any) => event.type === HttpEventType.UploadProgress || event.type === HttpEventType.Response),
      map((event: HttpEvent<string>) => {
        return event.type === HttpEventType.UploadProgress
          ? new UploadProgress(event.loaded, event.total)
          : new UploadProgress().innerData((event as HttpResponse<any>).body);
      }),
    );
  }

  private pollTask(uid: string, statusUrl: string): Observable<LongTask> {
    return pollUntil(this.api.get<LongTask>(statusUrl).pipe(map(withTaskDates)), isLongTaskDone, {
      onTimeout: (last) => ({ ...(last ?? { uid, steps: [] }), detailStatus: 'TIMEOUT' }),
    });
  }

  private formatAcl(val: AclResponse | null): Acl {
    const allows: AclAllow[] = Object.entries(val?.allows ?? {}).map(([k, v]) => ({
      name: v.name ? v.name : k,
      allowed: v.allowed,
      description: v.reason,
    }));
    return {
      allows: allows,
      fields: val?.fields,
    };
  }

  private extractFileNameFromHeader(disposition: string): string | null {
    const match = disposition.match(/filename\*?=(?:UTF-8'')?"?([^";]+)"?/i);
    if (match && match[1]) {
      try {
        return decodeURIComponent(match[1]);
      } catch {
        return match[1];
      }
    }
    return null;
  }
}
